import hashlib,json,pathlib,re
root=pathlib.Path('docs/evidence/heb-154/agent-code-v2')
path=root/'scenarios/proposed/wire-identity-examples.json'
data=json.loads(path.read_text())
pack_path=root/'scenarios/proposed/scenario-pack.json'
pack=json.loads(pack_path.read_text())
def sha(b): return 'sha256:'+hashlib.sha256(b).hexdigest()
def canonical(v):
    def subset(x):
        if x is None or isinstance(x,(str,bool)): return
        if type(x) is int: assert 0 <= x <= 9007199254740991
        elif isinstance(x,list):
            for y in x: subset(y)
        elif isinstance(x,dict):
            assert all(k.isascii() for k in x)
            for y in x.values(): subset(y)
        else: raise AssertionError('outside_specimen_subset')
    subset(v)
    return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def check_vector(v):
    actual=canonical(v['value'])
    preimage=v['domain'].encode()+b'\0'+actual
    if actual.decode()!=v['canonical_utf8'] or preimage.hex()!=v['preimage_hex'] or sha(preimage)!=v['sha256']:
        raise ValueError('vector_identity_mismatch')
def check_source(s):
    obj=pack
    for part in s['json_pointer'].split('/')[1:]:
        obj=obj[int(part)] if isinstance(obj,list) else obj[part]
    raw=canonical(obj)
    if s['input_pack_sha256']!=sha(pack_path.read_bytes()) or raw.decode()!=s['body_utf8'] or len(raw)!=s['body_length_bytes'] or sha(raw)!=s['source_ref']['content_digest']:
        raise ValueError('source_identity_mismatch')
for s in data['sources']: check_source(s)
for v in data['semantic_vectors']: check_vector(v)
vs={v['id']:v for v in data['semantic_vectors']}
assert len(vs)==len(data['semantic_vectors'])
for t in data['transmissions']:
    raw=t['raw_utf8'].encode()
    assert len(raw)==t['raw_length_bytes'] and sha(raw)==t['raw_sha256']
    req=json.loads(raw)
    assert req==t['request']
    p=req['payload']
    value={'run_id':req['run_id'],'order_id':req['order_id'],'operation_kind':req['action'],**{k:p[k] for k in ['plan_digest','approval_id','grant_digest','expected_order_revision','terms','reservation_id']}}
    assert sha(b'frd/effect/v1\0'+canonical(value))==p['semantic_effect_digest']==t['expected_semantic_effect_digest']==vs['reserve-effect']['sha256']
assert len({t['raw_sha256'] for t in data['transmissions']})==len(data['transmissions'])
for dirty_id in ['arrangement-effect','changed-quantity','changed-authority']:
    assert vs[dirty_id]['sha256']!=vs['reserve-effect']['sha256']
controls=[]
for name,fn,specimen in [('wrong_vector_digest',check_vector,{**vs['plan'],'sha256':'sha256:'+'0'*64}),('normalized_source_bytes',check_source,{**data['sources'][0],'body_utf8':data['sources'][0]['body_utf8']+'\n'})]:
    try: fn(specimen)
    except ValueError: controls.append(name)
    else: raise AssertionError('inert_detector:'+name)
assert sha(b'frd/grant/v1\0'+canonical(vs['plan']['value']))!=vs['plan']['sha256']
controls+=['operation_kind_or_reservation_changed','quantity_changed','grant_digest_changed','domain_changed']
def strict_specimen(s):
    def pairs(ps):
        d={}
        for k,v in ps:
            if k in d: raise ValueError('duplicate_decoded_key')
            d[k]=v
        return d
    def integer(s):
        if not re.fullmatch(r'0|[1-9][0-9]*',s): raise ValueError('numeric_lexeme')
        n=int(s)
        if n>9007199254740991: raise ValueError('numeric_range')
        return n
    def reject(s): raise ValueError('numeric_lexeme')
    return json.loads(s,object_pairs_hook=pairs,parse_int=integer,parse_float=reject,parse_constant=reject)
assert strict_specimen('{"quantity":2}')=={'quantity':2}
for v in data['rejection_examples']:
    try: strict_specimen(v['raw_utf8'])
    except ValueError: controls.append(v['id'])
    else: raise AssertionError('inert_rejection:'+v['id'])
doc=(root/'wire-and-identity-contract.md').read_text()
parent=(root/'execution-contract.md').read_text()
q=chr(96)
pattern=r'^\| '+q+r'([^'+q+r']+)'+q+r' \|'
expected=['order_context.read','source.read','availability.read','requirements.clarify','approval.request','inventory.reserve','arrangement.record','operation.reconcile','operation.cancel']
assert all(a in re.findall(pattern,parent,re.M) for a in expected)
def metadata(s):
    actual=[a for a in re.findall(pattern,s,re.M) if a in expected]
    if actual!=expected: raise ValueError('action_inventory')
    if re.findall(r'^\| (WIRE-[a-z]+) \|',s,re.M)!=['WIRE-envelope','WIRE-identity','WIRE-sources','WIRE-outcomes']: raise ValueError('decision_inventory')
    if '| Status | PROPOSED;' not in s: raise ValueError('proposal_status')
    if not set(re.findall(r'\bFRDX-[a-z-]+\b',s))<=set(re.findall(r'\bFRDX-[a-z-]+\b',parent)): raise ValueError('unknown_obligation')
metadata(doc)
for name,s in [('missing_action',doc.replace('| '+q+'source.read'+q+' |','| '+q+'omitted.read'+q+' |',1)),('false_implemented',doc.replace('| Status | PROPOSED;','| Status | IMPLEMENTED;',1)),('unknown_obligation',doc+'\nFRDX-unknown\n')]:
    try: metadata(s)
    except ValueError: controls.append(name)
    else: raise AssertionError('inert_metadata:'+name)
print(json.dumps({'result':'wire_authoring_checks_passed','scope':'Every authored identity vector, transmission and rejection specimen; exact public-pack JSON pointers for two example sources; all nine proposed public action rows and four WIRE decision rows, proposal marker and FRDX references. Python independently recomputes the Node-generated integer/ASCII-key subset only. No general JCS conformance, machine-schema validation, real HTTP parser, SQL finality, policy, complete source materialization, hidden/provider population or agent proof.','semantic_vector_ids':list(vs),'transmission_ids':[t['id'] for t in data['transmissions']],'rejection_ids':[v['id'] for v in data['rejection_examples']],'authoring_dirty_controls_detected':controls,'input_sha256':{str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [path,pack_path,root/'wire-and-identity-contract.md',root/'execution-contract.md']}},indent=2))
